messages.content:
Tool response:
Tool: create_quote
Description: Create Quote
Parameters:
    {
      "type": "object",
      "properties": {
        "customer_name": {
          "type": "string",
          "title": "Customer Name"
        },
        "vehicle_vin": {
          "type": "string",
          "title": "Vehicle Vin"
        },
        "price": {
          "type": "number",
          "title": "Price"
        },
        "discount": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Discount",
          "default": 0
        },
        "expiration_date": {
          "type": "string",
          "title": "Expiration Date"
        }
      },
      "required": [
        "customer_name",
        "vehicle_vin",
        "price",
        "expiration_date"
      ]
    }
